#!/bin/sh
# Build bytepeel.wasm from the workspace (needs the wasm32-unknown-unknown target).
set -eu
cd "$(dirname "$0")/.."
cargo build --profile wasm --target wasm32-unknown-unknown -p bytepeel-wasm
cp target/wasm32-unknown-unknown/wasm/bytepeel_wasm.wasm npm/bytepeel.wasm
cp LICENSE npm/LICENSE
ls -l npm/bytepeel.wasm
# JSR: the wasm embedded as base64, so Deno loads it without read/net permissions.
node -e '
const fs = require("fs");
const b64 = fs.readFileSync("npm/bytepeel.wasm").toString("base64");
fs.writeFileSync("npm/bytepeel_wasm.js",
  "// Generated by build.sh: bytepeel.wasm as base64.\n" +
  "// @ts-self-types=\"./bytepeel_wasm.d.ts\"\n" +
  "export default \"" + b64 + "\";\n");
'
